let now = function () {
  return new Date()
}

export default {
  name: "ExpirationInput",
  components: { DateTimePicker },
  props: {
    modelValue: {
      type: [Date, String],
      default: null,
    },
    label: {
      type: String,
      default: "Expiration",
    },
  },

  data() {
    return {
      menu: false,
      expirationShortcuts: [
        { title: "1 day", expiration: addDays(now(), 1) },
        {
          title: "7 days",
          expiration: addDays(now(), 7),
        },
        {
          title: "30 days",
          expiration: addDays(now(), 30),
        },
        {
          title: "60 days",
          expiration: addDays(now(), 60),
        },
      ],
    }
  },

  computed: {
    expiration: {
      get() {
        return cloneDeep(this.modelValue)
      },
      set(value) {
        this.$emit("update:modelValue", value)
      },
    },
  },

  methods: {
    setExpiration: function (value) {
      this.expiration = this.toLocalISOString(value)
    },
    clearExpiration: function () {
      this.expiration = null
    },
    closeMenu: function () {
      this.menu = false
    },
    toLocalISOString: function (date) {
      let tzOffset = date.getTimezoneOffset() * 60000 // offset in milliseconds
      return new Date(date - tzOffset).toISOString().slice(0, -1)
    },
  },
}
</script>
